import React from 'react';
import QuestionLayout from '../ui/QuestionLayout';
import OptionChipGroup from '../ui/OptionChipGroup';
import MiniFormSolicitor from '../ui/MiniFormSolicitor';
import { useClaim } from '../../context/ClaimContext';

const EMPTY_SOLICITOR = {
  dateOfIncident: null as string | null,
  solicitorName: '',
  caseHandler: '',
  solicitorAddress: '',
  solicitorPhone: '',
  solicitorEmail: '',
  caseReference: '',
};

export const Step8Responsibility: React.FC = () => {
  const { state, dispatch, updateSolicitorDetails } = useClaim();

  const options = [
    { label: 'Yes', value: true },
    { label: 'No', value: false },
  ];

  const handleSelect = (value: boolean) => {
    dispatch({
      type: 'UPDATE_FIELD',
      field: 'hasLegalResponsibility',
      value,
    });
    if (value && !state.solicitorDetails) {
      dispatch({
        type: 'UPDATE_FIELD',
        field: 'solicitorDetails',
        value: { ...EMPTY_SOLICITOR },
      });
    }
  };

  const handleSolicitorChange = (updates: Partial<NonNullable<typeof state.solicitorDetails>>) => {
    updateSolicitorDetails(updates);
  };

  return (
    <QuestionLayout
      partLabel="Part 3 – Background details"
      currentIndex={2}
      total={2}
      question="Is another person or company legally responsible for this condition?"
    >
      <OptionChipGroup
        options={options}
        value={state.hasLegalResponsibility}
        onChange={handleSelect}
      />

      {state.hasLegalResponsibility === true && (
        <div className="mt-4">
          <MiniFormSolicitor
            value={state.solicitorDetails}
            onChange={handleSolicitorChange}
          />
        </div>
      )}
    </QuestionLayout>
  );
};

export default Step8Responsibility;
