'use client';

import React, { createContext, useContext, useReducer, ReactNode } from 'react';
import { ClaimState, ClaimAction } from '../types/claim';
import { getNextStep, getPreviousStep } from '../lib/navigation-logic';

// 1. Initial State
const initialState: ClaimState = {
  currentStep: 'ONBOARDING',
  responses: {},
  history: []
};

// 2. Reducer Logic
function claimReducer(state: ClaimState, action: ClaimAction): ClaimState {
  switch (action.type) {
    case 'UPDATE_FIELD':
      return {
        ...state,
        responses: { ...state.responses, [action.payload.field]: action.payload.value }
      };
    case 'NEXT_STEP':
      return {
        ...state,
        history: [...state.history, state.currentStep],
        currentStep: getNextStep(state)
      };
    case 'PREVIOUS_STEP':
      return {
        ...state,
        currentStep: getPreviousStep(state),
        history: state.history.slice(0, -1)
      };
    default:
      return state;
  }
}

// 3. Create Context
const ClaimContext = createContext<{
  state: ClaimState;
  dispatch: React.Dispatch<ClaimAction>;
} | undefined>(undefined);

// 4. The Provider (The component that wraps your app)
export const ClaimProvider = ({ children }: { children: ReactNode }) => {
  const [state, dispatch] = useReducer(claimReducer, initialState);
  return (
    <ClaimContext.Provider value={{ state, dispatch }}>
      {children}
    </ClaimContext.Provider>
  );
};

// 5. The Hook (What your steps use to get data)
export const useClaim = () => {
  const context = useContext(ClaimContext);
  if (!context) {
    throw new Error('useClaim must be used within a ClaimProvider');
  }
  return context;
};