import React from 'react';

type OptionChipProps = {
  label: string;
  description?: string;
  selected?: boolean;
  disabled?: boolean;
  onClick?: () => void;
  className?: string;
};

/**
 * OptionChip
 *
 * Figma variable mapping (approx):
 * - Min width / max width: 280–600px (Alias/Size/OptionChip)
 * - Radius: 8px (Alias/Radius/radius-sm → rounded-lg)
 * - Border: #d2d3d6 (Alias/Border/border-general-default)
 * - Selected border: #0055b7 (Alias/Border/border-brand-primary-default)
 * - Background selected: #cce9fb (Alias/Background/bg-brand-secondary-default)
 * - Label text: #4d4f5c (Alias/Text/text-label-default)
 */
export const OptionChip: React.FC<OptionChipProps> = ({
  label,
  description,
  selected = false,
  disabled = false,
  onClick,
  className = '',
}) => {
  const baseClasses =
    'w-full min-w-[280px] max-w-[600px] text-left rounded-lg border px-4 py-3 transition flex items-start gap-3';

  const stateClasses = selected
    ? 'border-[#0055b7] bg-[#cce9fb]'
    : 'border-[#d2d3d6] bg-white hover:border-[#0055b7]/60 hover:bg-[#f6f6f7]';

  const disabledClasses = disabled
    ? 'opacity-50 cursor-not-allowed hover:border-[#d2d3d6] hover:bg-white'
    : 'cursor-pointer';

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      className={`${baseClasses} ${stateClasses} ${disabledClasses} ${className}`}
    >
      <span
        className={`mt-[6px] h-4 w-4 rounded-full border ${
          selected ? 'border-[#0055b7] bg-[#0055b7]' : 'border-[#d2d3d6] bg-white'
        }`}
        aria-hidden="true"
      />
      <span className="flex flex-col">
        <span className="text-[16px] leading-[28px] font-medium text-[#4d4f5c]">{label}</span>
        {description && (
          <span className="mt-1 text-[14px] leading-[24px] text-[#4d4f5c] opacity-80">
            {description}
          </span>
        )}
      </span>
    </button>
  );
};

export default OptionChip;

