import React from 'react';
import type {
  InjuryDetails,
  SportingInjuryDetails,
  TripFallDetails,
  TrafficAccidentDetails,
  AttackAssaultDetails,
  TrafficAccidentRole,
} from '../../types/claim';

const inputClass =
  'w-full rounded-lg border border-[#d2d3d6] bg-white px-3 py-2 text-[16px] leading-[28px] text-[#4d4f5c] placeholder:text-[#949494] focus:outline-none focus:border-[#0055b7]';
const labelClass = 'block text-[14px] leading-[24px] font-medium text-[#4d4f5c] mb-1';
const chipClass = (selected: boolean) =>
  `rounded-lg border px-4 py-2 text-[14px] leading-[24px] font-medium transition ${
    selected ? 'border-[#0055b7] bg-[#cce9fb] text-[#0055b7]' : 'border-[#d2d3d6] bg-white text-[#4d4f5c] hover:bg-[#f6f6f7]'
  }`;

type InjuryFormVariantProps = {
  injuryDetails: InjuryDetails;
  onChange: (updates: Partial<InjuryDetails>) => void;
  className?: string;
};

/** question=7, type=sporting injury */
export const MiniFormInjurySporting: React.FC<InjuryFormVariantProps> = ({
  injuryDetails,
  onChange,
  className = '',
}) => {
  const d = (injuryDetails.sporting || { sport: '', country: '', receivedDonation: null }) as SportingInjuryDetails;
  const update = (u: Partial<SportingInjuryDetails>) =>
    onChange({ sporting: { ...d, ...u } });
  return (
    <div className={`rounded-lg border border-[#d2d3d6] bg-white p-4 space-y-4 ${className}`} data-variant="q7-sporting">
      <div>
        <label className={labelClass}>Where did this happen?</label>
        <input
          type="text"
          value={d.country}
          onChange={(e) => update({ country: e.target.value })}
          placeholder="e.g. United Kingdom"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Sport or activity</label>
        <input
          type="text"
          value={d.sport}
          onChange={(e) => update({ sport: e.target.value })}
          placeholder="e.g. Football, Rugby"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Did you receive a donation or payment related to this activity?</label>
        <div className="flex gap-3 flex-wrap">
          <button type="button" onClick={() => update({ receivedDonation: true })} className={chipClass(d.receivedDonation === true)}>Yes</button>
          <button type="button" onClick={() => update({ receivedDonation: false })} className={chipClass(d.receivedDonation === false)}>No</button>
        </div>
      </div>
    </div>
  );
};

