/** question=7, type=traffic accident */
export const MiniFormInjuryTraffic: React.FC<InjuryFormVariantProps> = ({
  injuryDetails,
  onChange,
  className = '',
}) => {
  const d = (injuryDetails.traffic || {
    role: null,
    incidentDescription: '',
    criminalProceedings: '',
    country: '',
  }) as TrafficAccidentDetails;
  const update = (u: Partial<TrafficAccidentDetails>) =>
    onChange({ traffic: { ...d, ...u } });
  const roles: { value: TrafficAccidentRole; label: string }[] = [
    { value: 'motorcycle_bicycle', label: 'Motorcycle / Bicycle' },
    { value: 'motor_vehicle', label: 'Motor vehicle' },
    { value: 'pedestrian', label: 'Pedestrian' },
  ];
  return (
    <div className={`rounded-lg border border-[#d2d3d6] bg-white p-4 space-y-4 ${className}`} data-variant="q7-traffic">
      <div>
        <label className={labelClass}>Where did this happen?</label>
        <input type="text" value={d.country} onChange={(e) => update({ country: e.target.value })} placeholder="e.g. United Kingdom" className={inputClass} />
      </div>
      <div>
        <label className={labelClass}>Your role</label>
        <div className="flex gap-3 flex-wrap">
          {roles.map((r) => (
            <button key={r.value} type="button" onClick={() => update({ role: r.value })} className={chipClass(d.role === r.value)}>{r.label}</button>
          ))}
        </div>
      </div>
      <div>
        <label className={labelClass}>Incident description</label>
        <textarea value={d.incidentDescription} onChange={(e) => update({ incidentDescription: e.target.value })} placeholder="Brief description" rows={3} className={inputClass} />
      </div>
      <div>
        <label className={labelClass}>Criminal proceedings</label>
        <input type="text" value={d.criminalProceedings} onChange={(e) => update({ criminalProceedings: e.target.value })} placeholder="If applicable" className={inputClass} />
      </div>
    </div>
  );
};

