import React, { useState, useCallback } from 'react';
import QuestionLayout from '../ui/QuestionLayout';
import { SearchInput } from '../ui/SearchInput';
import { LoadingIndicator } from '../ui/LoadingIndicator';
import { SnomedResultTile } from '../ui/SnomedResultTile';
import ModalOverlay from '../ui/ModalOverlay';
import { useClaim } from '../../context/ClaimContext';
import { fetchSnomed, fetchSnomedSuggestions } from '../../hooks/useSnomed';
import type { SnomedCode } from '../../types/claim';

const SUGGESTION_LIMIT = 4;

export const Step4SymptomDescribe: React.FC = () => {
  const { dispatch } = useClaim();
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<SnomedCode | null>(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [suggestions, setSuggestions] = useState<SnomedCode[]>([]);
  const [suggestionsLoading, setSuggestionsLoading] = useState(false);

  const handleSearchChange = async (value: string) => {
    setQuery(value);
    if (!value.trim()) {
      setResult(null);
      return;
    }
    setLoading(true);
    try {
      const res = await fetchSnomed(value);
      setResult(res);
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = useCallback(() => {
    if (!result) return;
    dispatch({
      type: 'UPDATE_SYMPTOM',
      updates: {
        snomedCode: result,
        userInput: query,
        isConfirmed: true,
      },
    });
  }, [result, query, dispatch]);

  const handleSomethingElse = useCallback(async () => {
    setResult(null);
    setModalOpen(true);
    const searchQuery = query.trim() || 'symptom';
    setSuggestionsLoading(true);
    try {
      const list = await fetchSnomedSuggestions(searchQuery, SUGGESTION_LIMIT);
      setSuggestions(list);
    } finally {
      setSuggestionsLoading(false);
    }
  }, [query]);

  const handleSelectSuggestion = useCallback((code: SnomedCode) => {
    dispatch({
      type: 'UPDATE_SYMPTOM',
      updates: {
        snomedCode: code,
        userInput: code.name,
        isConfirmed: true,
      },
    });
    setModalOpen(false);
    setSuggestions([]);
    setQuery(code.name);
  }, [dispatch]);

  return (
    <QuestionLayout
      partLabel="Part 2 – Symptoms & condition"
      currentIndex={3}
      total={6}
      question="How would you describe your main symptom?"
    >
      <SearchInput
        value={query}
        onChange={handleSearchChange}
        placeholder="Describe your main symptom…"
        autoFocus
      />

      {loading && <LoadingIndicator label="Looking up SNOMED matches…" />}

      {!loading && result && (
        <SnomedResultTile
          code={result.code}
          name={result.name}
          description={result.description}
          onConfirm={handleConfirm}
          onSomethingElse={handleSomethingElse}
        />
      )}

      <ModalOverlay
        open={modalOpen}
        onClose={() => { setModalOpen(false); setSuggestions([]); }}
        title="Choose a suggestion"
      >
        {suggestionsLoading ? (
          <LoadingIndicator label="Loading suggestions…" />
        ) : (
          <div className="space-y-3">
            {suggestions.map((item) => (
              <button
                key={item.code}
                type="button"
                onClick={() => handleSelectSuggestion(item)}
                className="w-full rounded-lg border border-[#d2d3d6] bg-white p-3 text-left transition hover:border-[#0055b7] hover:bg-[#f6f6f7]"
              >
                <span className="text-[14px] leading-[24px] text-[#949494]">{item.code}</span>
                <div className="font-medium text-[16px] leading-[28px] text-[#4d4f5c]">{item.name}</div>
                {item.description && (
                  <div className="text-[14px] leading-[24px] text-[#4d4f5c] opacity-80">{item.description}</div>
                )}
              </button>
            ))}
            {!suggestionsLoading && suggestions.length === 0 && (
              <p className="text-[14px] leading-[24px] text-[#4d4f5c]">No suggestions found. Try searching again.</p>
            )}
            <button
              type="button"
              onClick={() => { setModalOpen(false); setSuggestions([]); }}
              className="mt-2 w-full rounded-lg border border-[#d2d3d6] px-4 py-2 text-[16px] leading-[28px] font-medium text-[#4d4f5c] hover:bg-[#f6f6f7]"
            >
              Search again
            </button>
          </div>
        )}
      </ModalOverlay>
    </QuestionLayout>
  );
};

export default Step4SymptomDescribe;
