import React, { ReactNode } from 'react';

type ModalOverlayProps = {
  open: boolean;
  onClose: () => void;
  title?: string;
  children: ReactNode;
  className?: string;
};

/**
 * ModalOverlay – backdrop + panel for modals (e.g. SNOMED suggestions).
 * Figma: border #d2d3d6, radius 8px, bg white, text #4d4f5c
 */
export const ModalOverlay: React.FC<ModalOverlayProps> = ({
  open,
  onClose,
  title,
  children,
  className = '',
}) => {
  if (!open) return null;

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4"
      role="dialog"
      aria-modal="true"
      aria-labelledby={title ? 'modal-title' : undefined}
    >
      <div
        className="absolute inset-0 bg-black/40"
        onClick={onClose}
        onKeyDown={(e) => e.key === 'Escape' && onClose()}
        aria-hidden="true"
      />
      <div
        className={`relative w-full max-w-md rounded-lg border border-[#d2d3d6] bg-white p-4 shadow-lg ${className}`}
        onClick={(e) => e.stopPropagation()}
      >
        {title && (
          <h3 id="modal-title" className="text-[18px] leading-[32px] font-medium text-[#4d4f5c] mb-3">
            {title}
          </h3>
        )}
        <button
          type="button"
          onClick={onClose}
          className="absolute top-3 right-3 text-[#4d4f5c] hover:text-[#0055b7] focus:outline-none"
          aria-label="Close"
        >
          <span className="text-xl leading-none">&times;</span>
        </button>
        {children}
      </div>
    </div>
  );
};

export default ModalOverlay;
