import React, { ReactNode } from 'react';
import { AnimatePresence, motion } from 'framer-motion';

import { ClaimProvider, useClaim } from '@/context/ClaimContext';
import { CLAIM_STAGES } from '../context/navigation-logic';

type AppShellProps = {
  children: ReactNode;
};

/**
 * AppShell
 * - Fixed TopBar + StageTrackerBar at the top
 * - Main content area in the middle with animated step transitions
 * - Fixed GlobalActions (Back / Continue) at the bottom
 *
 * Tailwind styling is mapped to Figma variables, e.g.:
 * - Backgrounds: bg-[#fafbfb] (bg-general-secondary), bg-white (bg-general-primary)
 * - Brand: #0055b7 (bg-brand-primary / text-brand-primary)
 * - Borders: #d2d3d6 (border-general-default)
 * - Radius: rounded-lg (= radius-sm 8px)
 * - Spacing: px-6/px-4/py-4 (= 24/16px padding), px-24 (= 96px page margin desktop)
 */
export const AppShell: React.FC<AppShellProps> = ({ children }) => {
  return (
    <ClaimProvider>
      <div className="min-h-screen bg-[#fafbfb] text-[#4d4f5c] flex flex-col">
        {/* Top chrome (fixed) */}
        <header className="fixed inset-x-0 top-0 z-40 bg-[#fafbfb]/90 backdrop-blur border-b border-[#d2d3d6]">
          <div className="mx-auto max-w-4xl px-6 pt-6 pb-3">
            <TopBar />
          </div>
          <div className="mx-auto max-w-4xl px-6 pb-3">
            <StageTrackerBar />
          </div>
        </header>

        {/* Main content with space for fixed header and footer */}
        <main className="flex-1 mx-auto w-full max-w-4xl px-6 pt-32 pb-28">
          <AnimatedStepContainer>{children}</AnimatedStepContainer>
        </main>

        {/* Bottom global actions (fixed) */}
        <footer className="fixed inset-x-0 bottom-0 z-40 bg-white/95 backdrop-blur border-t border-[#d2d3d6]">
          <div className="mx-auto max-w-4xl px-6 py-4">
            <GlobalActions />
          </div>
        </footer>
      </div>
    </ClaimProvider>
  );
};

const TopBar: React.FC = () => {
  return (
    <div className="flex items-center justify-between">
      <div className="flex flex-col">
        <span className="text-sm font-medium text-[#0055b7] tracking-wide uppercase">
          Health claim
        </span>
        <h1 className="text-[24px] leading-[40px] font-semibold text-[#4d4f5c]">
          Tell us about your claim
        </h1>
      </div>
      {/* Right-side slot for logo or avatar as needed */}
      <div className="h-10 w-10 rounded-full bg-[#cce9fb]" />
    </div>
  );
};

const StageTrackerBar: React.FC = () => {
  const { state } = useClaim();

  const activeIndex = CLAIM_STAGES.findIndex((stage) =>
    stage.steps.includes(state.currentStep)
  );

  return (
    <nav aria-label="Claim progress" className="flex items-center justify-between gap-2">
      {CLAIM_STAGES.map((stage, index) => {
        const isActive = index === activeIndex;
        const isCompleted = activeIndex > index;

        const dotColor = isActive
          ? '#0055b7' // bg-brand-primary-default
          : isCompleted
          ? '#1276c0' // bg-brand-accent-1
          : '#d2d3d6'; // bg-progress-step-incomplete

        const labelColor = isActive ? '#0055b7' : '#4d4f5c';

        return (
          <div key={stage.id} className="flex-1 flex flex-col items-center">
            <div className="flex items-center w-full">
              {/* Left connector */}
              {index > 0 && (
                <div
                  className={`h-[2px] flex-1 transition-colors ${
                    isCompleted ? 'bg-[#0055b7]' : 'bg-[#d2d3d6]'
                  }`}
                />
              )}

              {/* Dot */}
              <div
                className="flex h-4 w-4 items-center justify-center rounded-full border border-white shadow-sm"
                style={{ backgroundColor: dotColor }}
              />

              {/* Right connector */}
              {index < CLAIM_STAGES.length - 1 && (
                <div
                  className={`h-[2px] flex-1 transition-colors ${
                    activeIndex > index ? 'bg-[#0055b7]' : 'bg-[#d2d3d6]'
                  }`}
                />
              )}
            </div>
            <span
              className="mt-2 text-[14px] leading-[24px] text-center font-medium truncate"
              style={{ color: labelColor }}
            >
              {stage.label}
            </span>
          </div>
        );
      })}
    </nav>
  );
};

const AnimatedStepContainer: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { state } = useClaim();

  return (
    <AnimatePresence initial={false} mode="wait">
      <motion.div
        key={state.currentStep}
        initial={{ x: 32, opacity: 0 }}
        animate={{ x: 0, opacity: 1 }}
        exit={{ x: -32, opacity: 0 }}
        transition={{ duration: 0.25, ease: 'easeOut' }}
        className="h-full"
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
};

const GlobalActions: React.FC = () => {
  const { state, goToPreviousStep, goToNextStep, canProceed } = useClaim();

  const isOnboarding = state.currentStep === 'ONBOARDING';
  const isFirstStep = state.currentStep === 'Q1' || isOnboarding;
  const isContinueDisabled = !canProceed();

  return (
    <div className="flex items-center justify-between gap-4">
      {!isOnboarding && (
        <button
          type="button"
          onClick={goToPreviousStep}
          disabled={isFirstStep}
          className={`inline-flex h-12 items-center justify-center rounded-lg border px-4 text-[16px] leading-[28px] font-medium transition
            ${
              isFirstStep
                ? 'border-[#d2d3d6] text-[#d2d3d6] cursor-default'
                : 'border-[#d2d3d6] text-[#4d4f5c] hover:bg-[#f6f6f7]'
            }`}
        >
          Back
        </button>
      )}

      <button
        type="button"
        onClick={goToNextStep}
        disabled={isContinueDisabled}
        className={`inline-flex h-12 min-w-[140px] items-center justify-center rounded-lg px-6 text-[16px] leading-[28px] font-medium text-white transition
          ${
            isContinueDisabled
              ? 'bg-[#f6f6f7] text-[#d2d3d6] cursor-not-allowed'
              : 'bg-[#0055b7] hover:bg-[#1276c0]'
          }`}
      >
        Continue
      </button>
    </div>
  );
};

export default AppShell;

