import React, { ReactNode } from 'react';
import { motion } from 'framer-motion';

import { QuestionTag } from './QuestionTag';

type QuestionLayoutProps = {
  partLabel: string;
  currentIndex: number;
  total: number;
  question: string;
  description?: string;
  children: ReactNode;
  className?: string;
};

/**
 * QuestionLayout
 *
 * Structure:
 * - QuestionTag at the very top
 * - Question text + description
 * - Content slot (children) for controls (chips, search, etc.)
 *
 * Framer Motion:
 * - Enter: slide in from right (100% → 0%)
 * - Exit: slide out to left (0% → -100%)
 *
 * Figma variable mapping (approx):
 * - Question: 24px / 40px, font-semibold (title-page-md)
 * - Description: 16px / 28px (body)
 * - Spacing: 16–24px vertical gaps (padding-xs / padding-sm)
 */
export const QuestionLayout: React.FC<QuestionLayoutProps> = ({
  partLabel,
  currentIndex,
  total,
  question,
  description,
  children,
  className = '',
}) => {
  return (
    <motion.section
      className={`flex flex-col gap-4 ${className}`}
      initial={{ x: '100%', opacity: 0 }}
      animate={{ x: '0%', opacity: 1 }}
      exit={{ x: '-100%', opacity: 0 }}
      transition={{ duration: 0.25, ease: 'easeOut' }}
    >
      {/* Tag at the very top */}
      <QuestionTag partLabel={partLabel} currentIndex={currentIndex} total={total} />

      {/* Question text + description */}
      <header className="mt-2 space-y-2">
        <h2 className="text-[24px] leading-[40px] font-semibold text-[#4d4f5c]">
          {question}
        </h2>
        {description && (
          <p className="text-[16px] leading-[28px] text-[#4d4f5c]">{description}</p>
        )}
      </header>

      {/* Content slot for inputs (chips, search, etc.) */}
      <div className="mt-4 space-y-3">{children}</div>
    </motion.section>
  );
};

export default QuestionLayout;

